using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        AssetDatabase.Refresh();
        AssetDatabase.SaveAssets();
        result.Log("Refreshed AssetDatabase.");
        int n = 0, metas = 0;
        foreach (var f in System.IO.Directory.GetFiles("Assets/Resources/HUDTree/Atlases/Kit", "*", System.IO.SearchOption.AllDirectories))
        {
            if (f.EndsWith(".meta")) { metas++; continue; }
            if (f.EndsWith(".png"))
            {
                n++;
                var t = AssetDatabase.LoadAssetAtPath<Texture2D>(f);
                result.Log("  " + f + " -> " + (t == null ? "NULL" : ("Texture2D " + t.width + "x" + t.height)));
            }
            else if (f.EndsWith(".uxml") || f.EndsWith(".uss"))
            {
                var ut = AssetDatabase.LoadAssetAtPath<Object>(f);
                result.Log("  " + f + " -> " + (ut == null ? "NULL" : ut.GetType().Name));
            }
        }
        result.Log("summary: " + n + " png + " + metas + " meta files");
    }
}
